// Made by scripts/embed-dashboard.mjs from server/dashboard/index.html. Edit that file, not this one.
const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>Board Battles · Control room</title>\n<style>\n:root{--bg:#120c08;--panel:#1c130d;--panel2:#241810;--line:#3a2a1e;--gold:#f3cd62;--gold2:#c9a25a;--text:#f4e6c8;--muted:#b9a88a;--ok:#4fae6a;--bad:#d4574a;--warn:#e0a03a;--ink:#1b120c}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,-apple-system,\"Segoe UI\",Tahoma,sans-serif}\na{color:var(--gold)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n.app{display:grid;grid-template-columns:220px 1fr;min-height:100vh}\nnav.side{background:#0d0805;border-right:1px solid var(--line);padding:16px 10px;position:sticky;top:0;height:100vh;overflow:auto}\n.brand{display:block;padding:4px 10px 16px;color:var(--gold);font-weight:800;font-size:16px}\n.brand small{display:block;color:var(--muted);font-weight:500;font-size:11px}\nnav.side a{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-radius:9px;color:var(--text);text-decoration:none;margin-bottom:2px}\nnav.side a:hover{background:var(--panel)}\nnav.side a.on{background:var(--gold);color:var(--ink);font-weight:700}\n.pill{background:var(--bad);color:#fff;border-radius:99px;font-size:11px;padding:0 7px;font-weight:700}\nnav.side a.on .pill{background:var(--ink);color:var(--gold)}\nmain{padding:22px 26px 60px;min-width:0}\nh1{font-size:22px;margin:0 0 4px;color:var(--gold)}\nh2{font-size:16px;margin:22px 0 10px;color:var(--gold)}\n.sub{color:var(--muted);font-size:13px}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px}\n.kpi .v{font-size:24px;font-weight:800;color:#fff;letter-spacing:.2px}\n.kpi .l{color:var(--muted);font-size:12px}\n.kpi.alert{border-color:var(--warn)}\n.flags{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}\n.flag{padding:4px 10px;border-radius:99px;font-size:12px;font-weight:700;background:var(--panel2);border:1px solid var(--line)}\n.flag.on{background:rgba(79,174,106,.15);border-color:var(--ok);color:#9fe0b0}\n.flag.off{color:var(--muted)}\n.flag.warn{background:rgba(224,160,58,.15);border-color:var(--warn);color:#ffd08a}\ntable{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}\nth,td{padding:9px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}\nth{color:var(--gold);font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.4px;background:var(--panel2)}\ntr:last-child td{border-bottom:0}\ntr.click{cursor:pointer} tr.click:hover td{background:var(--panel2)}\ntd.num,th.num{text-align:right;font-variant-numeric:tabular-nums}\n.tablewrap{overflow-x:auto}\n.btn{text-decoration:none;color:var(--text);border:1px solid var(--line);background:var(--panel2);border-radius:9px;padding:7px 12px;cursor:pointer;font-weight:600}\n.btn:hover{border-color:var(--gold2)}\n.btn.gold{background:var(--gold);color:var(--ink);border-color:var(--gold)}\n.btn.ok{background:var(--ok);border-color:var(--ok);color:#fff}\n.btn.bad{background:var(--bad);border-color:var(--bad);color:#fff}\n.btn.sm{padding:4px 9px;font-size:12px}\n.btn:disabled{opacity:.5;cursor:default}\ninput,select,textarea{background:#0d0805;border:1px solid var(--line);border-radius:9px;padding:7px 10px}\ninput:focus,select:focus,textarea:focus{outline:2px solid var(--gold2);outline-offset:-1px}\ninput[type=number]{width:150px}\ntd:first-child,td:nth-child(2){white-space:nowrap}\nlabel.f{display:grid;gap:4px;font-size:12px;color:var(--muted)}\nlabel.f input,label.f select,label.f textarea{color:var(--text);font-size:14px;width:100%;min-width:0}\nlabel.f input[type=color]{width:52px}\n.form{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(200px,1fr))}\n.switch{display:inline-flex;align-items:center;gap:8px;cursor:pointer;user-select:none}\n.switch input{width:38px;height:22px;appearance:none;background:var(--line);border-radius:99px;position:relative;cursor:pointer;padding:0;border:0}\n.switch input::after{content:\"\";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:.15s}\n.switch input:checked{background:var(--ok)}\n.switch input:checked::after{left:19px}\n.tabs{display:flex;gap:6px;margin:10px 0 14px;flex-wrap:wrap}\n.tabs button{border:1px solid var(--line);background:var(--panel);border-radius:99px;padding:5px 14px;cursor:pointer}\n.tabs button.on{background:var(--gold);color:var(--ink);border-color:var(--gold);font-weight:700}\n.chart{display:block;width:100%;height:auto}\n.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:var(--gold);color:var(--ink);padding:10px 18px;border-radius:10px;font-weight:700;box-shadow:0 10px 30px rgba(0,0,0,.5);z-index:50}\n.toast.err{background:var(--bad);color:#fff}\n.drawer{position:fixed;inset:0 0 0 auto;width:min(720px,100%);background:var(--bg);border-left:1px solid var(--line);overflow:auto;padding:20px 22px;z-index:40;box-shadow:-20px 0 40px rgba(0,0,0,.5)}\n.shade{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:30}\n.x{float:right}\n.muted{color:var(--muted)}\n.tag{display:inline-block;padding:1px 8px;border-radius:99px;font-size:11px;font-weight:700;background:var(--panel2);border:1px solid var(--line)}\n.tag.paid,.tag.on,.tag.google,.tag.apple{color:#9fe0b0;border-color:var(--ok)}\n.tag.pending{color:#ffd08a;border-color:var(--warn)}\n.tag.rejected,.tag.banned{color:#ff9d92;border-color:var(--bad)}\n.mono{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px}\n.bracket{display:flex;gap:18px;overflow-x:auto;padding-bottom:6px}\n.round{display:grid;gap:8px;align-content:center;min-width:170px}\n.match{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:6px 8px;font-size:12px}\n.match div{display:flex;justify-content:space-between}\n.match .w{color:var(--gold);font-weight:700}\n.ttl{--b:#fff;display:inline-flex;align-items:center;gap:6px;padding:3px 13px 3px 9px;border-radius:99px;border:1.5px solid var(--b);font-weight:800;font-size:13px;line-height:1.4;position:relative;overflow:hidden;white-space:nowrap;vertical-align:middle}\n.ttl svg{width:16px;height:16px;flex:none}\n.ttl.big{font-size:17px;padding:6px 18px 6px 12px}.ttl.big svg{width:21px;height:21px}\n.ttl.fx-shine::after{content:\"\";position:absolute;inset:0;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.55) 50%,transparent 65%);transform:translateX(-120%);animation:ttlshine 2.6s ease-in-out infinite}\n@keyframes ttlshine{0%{transform:translateX(-120%)}60%,100%{transform:translateX(120%)}}\n.ttl.fx-glow{animation:ttlglow 2s ease-in-out infinite}\n@keyframes ttlglow{0%,100%{box-shadow:0 0 0 0 transparent}50%{box-shadow:0 0 12px 1px var(--b)}}\n.ttl.fx-pulse{animation:ttlpulse 1.6s ease-in-out infinite}\n@keyframes ttlpulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}\n.tgrid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(290px,1fr))}\n.tcard{display:grid;gap:10px;align-content:start}\n.tcard .pv{display:grid;gap:8px;justify-items:center;padding:14px 8px;background:#0d0805;border-radius:10px}\n.iconpick{display:flex;flex-wrap:wrap;gap:6px}.iconpick button{width:38px;height:38px;border-radius:9px;border:1px solid var(--line);background:#0d0805;color:var(--text);cursor:pointer;display:grid;place-items:center}\n.iconpick button.on{border-color:var(--gold);background:var(--panel2)}.iconpick svg{width:20px;height:20px}\ninput[type=color]{width:52px;height:36px;padding:2px;cursor:pointer}\n.login{max-width:360px;margin:12vh auto;padding:26px}\n.empty{padding:22px;text-align:center;color:var(--muted)}\n.tierrow td{padding:5px 8px}\n.tierrow select,.tierrow input{padding:4px 6px}\n@media (max-width:820px){.app{grid-template-columns:1fr}nav.side{position:static;height:auto;display:flex;overflow-x:auto;gap:4px;padding:8px}nav.side .brand{display:none}nav.side a{white-space:nowrap}main{padding:16px}}\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<script>\n'use strict';\nconst $ = (s, r = document) => r.querySelector(s);\nconst esc = v => String(v ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst num = n => Number(n || 0).toLocaleString('en');\nconst short = n => { n = Number(n || 0); const a = Math.abs(n); return a >= 1e9 ? (n / 1e9).toFixed(a >= 1e10 ? 0 : 1) + 'B' : a >= 1e6 ? (n / 1e6).toFixed(a >= 1e7 ? 0 : 1) + 'M' : a >= 1e3 ? Math.round(n / 1e3) + 'K' : String(n); };\nconst cairo = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', dateStyle: 'medium', timeStyle: 'short' });\nconst when = t => t ? cairo.format(new Date(t)) : '—';\nconst ago = t => { if (!t) return '—'; const s = (Date.now() - t) / 1000; return s < 90 ? 'now' : s < 3600 ? Math.round(s / 60) + ' min ago' : s < 86400 ? Math.round(s / 3600) + ' h ago' : Math.round(s / 86400) + ' d ago'; };\nconst DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];\nconst GAMES = { rotate: 'Each week in turn', domino: 'Dominoes', tawla: 'Backgammon (tawla)', chess: 'Chess', ludo: 'Ludo' };\nlet state = { view: 'overview', catalog: null, pending: 0 };\n\nasync function api(path, opts = {}) {\n  const r = await fetch('/api/admin' + path, { method: opts.method || (opts.body ? 'POST' : 'GET'), headers: { 'Content-Type': 'application/json' }, body: opts.body ? JSON.stringify(opts.body) : undefined, credentials: 'same-origin' });\n  const j = await r.json().catch(() => ({}));\n  if (r.status === 401) { showLogin(); throw new Error('Signed out'); }\n  if (!r.ok) throw new Error(j.error || ('HTTP ' + r.status));\n  return j;\n}\nfunction toast(msg, err) { const t = document.createElement('div'); t.className = 'toast' + (err ? ' err' : ''); t.textContent = msg; document.body.appendChild(t); setTimeout(() => t.remove(), err ? 4500 : 2400); }\nasync function act(fn, ok) { try { const r = await fn(); if (ok) toast(ok); return r; } catch (e) { if (e.message !== 'Signed out') toast(e.message, true); throw e; } }\n\n/* ---------------- titles: drawn the same way as in the game ---------------- */\nfunction iconSvg(name) { const d = (state.catalog?.icons || {})[name]; return d ? '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" fill-rule=\"evenodd\" d=\"' + d + '\"/></svg>' : ''; }\nfunction badge(t, lang, big) {\n  if (!t) return '';\n  const s = t.style;\n  return '<span class=\"ttl fx-' + esc(s.effect) + (big ? ' big' : '') + '\" style=\"--b:' + esc(s.border) + ';background:linear-gradient(90deg,' + esc(s.bg[0]) + ',' + esc(s.bg[1]) + ');color:' + esc(s.fg) + '\"' + (lang === 'ar' ? ' dir=\"rtl\"' : '') + '>' + iconSvg(s.icon) + esc(lang === 'en' ? t.en : t.ar) + '</span>';\n}\nconst titleById = id => (state.catalog?.titles || []).find(t => t.id === id);\n\n/* ---------------- sign in ---------------- */\nfunction showLogin() {\n  $('#root').innerHTML = '<div class=\"card login\"><h1>Control room</h1><p class=\"sub\">Board Battles · enter the server\\'s ADMIN_KEY</p>' +\n    '<form id=\"lf\" class=\"row\" style=\"display:grid;gap:10px\"><input id=\"lk\" type=\"password\" placeholder=\"Admin key\" autocomplete=\"current-password\" required>' +\n    '<button class=\"btn gold\">Sign in</button><div id=\"le\" class=\"sub\"></div></form></div>';\n  $('#lf').onsubmit = async e => {\n    e.preventDefault();\n    try { await api('/login', { body: { key: $('#lk').value } }); start(); }\n    catch (er) { $('#le').textContent = er.message === 'admin_off' ? 'The dashboard is off: set ADMIN_KEY on the server.' : er.message === 'wrong_key' ? 'Wrong key.' : er.message; }\n  };\n  $('#lk').focus();\n}\n\n/* ---------------- the frame ---------------- */\nconst VIEWS = [\n  ['overview', 'Overview'], ['prizes', 'Monthly prizes'], ['players', 'Players'], ['rewards', 'Rewards & notices'],\n  ['tourney', 'Tournaments'], ['season', 'Season pass'], ['titles', 'Titles'], ['events', 'Events'], ['settings', 'Game settings'], ['reports', 'Reports & support'],\n  ['purchases', 'Purchases'], ['log', 'Activity log'],\n];\nfunction frame() {\n  $('#root').innerHTML = '<div class=\"app\"><nav class=\"side\"><div class=\"brand\">♛ Board Battles<small>Control room</small></div>' +\n    VIEWS.map(([k, l]) => '<a href=\"#' + k + '\" data-v=\"' + k + '\">' + l + (k === 'prizes' ? '<span class=\"pill\" id=\"pendpill\" hidden></span>' : '') + '</a>').join('') +\n    '<a href=\"#\" id=\"logout\" style=\"margin-top:14px\">Sign out</a></nav><main id=\"main\"></main></div>';\n  $('#logout').onclick = async e => { e.preventDefault(); await api('/logout', { body: {} }).catch(() => {}); showLogin(); };\n}\nfunction setPending(n) { state.pending = n; const p = $('#pendpill'); if (p) { p.hidden = !n; p.textContent = n; } }\nasync function go() {\n  closeDrawer();\n  const v = (location.hash.slice(1) || 'overview').split('/')[0];\n  state.view = VIEWS.some(x => x[0] === v) ? v : 'overview';\n  document.querySelectorAll('nav.side a[data-v]').forEach(a => a.classList.toggle('on', a.dataset.v === state.view));\n  const main = $('#main'); main.innerHTML = '<div class=\"empty\">Loading…</div>';\n  try { await RENDER[state.view](main); } catch (e) { if (e.message !== 'Signed out') main.innerHTML = '<div class=\"card\">Could not load: ' + esc(e.message) + '</div>'; }\n}\nasync function start() {\n  frame();\n  try { state.catalog = await api('/catalog'); } catch { return; }\n  window.onhashchange = go;\n  go();\n  setInterval(async () => { try { const o = await api('/overview'); setPending(o.prizePending); } catch {} }, 60000);\n}\n\n/* ---------------- charts (plain SVG) ---------------- */\nfunction bars(rows, key, label, color) {\n  const W = 460, H = 150, P = 14, max = Math.max(1, ...rows.map(r => r[key]));\n  const bw = (W - P * 2) / rows.length;\n  let s = '<svg class=\"chart\" viewBox=\"0 0 ' + W + ' ' + (H + 34) + '\" role=\"img\" aria-label=\"' + esc(label) + '\">';\n  s += '<text x=\"0\" y=\"14\" fill=\"#b9a88a\" font-size=\"14\" font-weight=\"600\">' + esc(label) + ' · last ' + rows.length + ' days</text>';\n  rows.forEach((r, i) => {\n    const h = Math.round((r[key] / max) * (H - 40)), x = P + i * bw + 3, y = H - h;\n    s += '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + (bw - 6) + '\" height=\"' + Math.max(1, h) + '\" rx=\"3\" fill=\"' + color + '\"><title>' + esc(r.day) + ': ' + num(r[key]) + '</title></rect>';\n    if (r[key]) s += '<text x=\"' + (x + (bw - 6) / 2) + '\" y=\"' + (y - 4) + '\" fill=\"#f4e6c8\" font-size=\"11\" text-anchor=\"middle\">' + short(r[key]) + '</text>';\n    if ((i % 3 === 0 && i < rows.length - 2) || i === rows.length - 1) s += '<text x=\"' + (x + (bw - 6) / 2) + '\" y=\"' + (H + 18) + '\" fill=\"#b9a88a\" font-size=\"11\" text-anchor=\"middle\">' + esc(r.day.slice(5)) + '</text>';\n  });\n  return s + '<line x1=\"' + P + '\" x2=\"' + (W - P) + '\" y1=\"' + H + '\" y2=\"' + H + '\" stroke=\"#3a2a1e\"/></svg>';\n}\n\nconst RENDER = {};\n\n/* ---------------- overview ---------------- */\nRENDER.overview = async main => {\n  const o = await api('/overview');\n  setPending(o.prizePending);\n  const k = (v, l, alert) => '<div class=\"card kpi' + (alert ? ' alert' : '') + '\"><div class=\"v\">' + v + '</div><div class=\"l\">' + l + '</div></div>';\n  const f = (on, l, warn) => '<span class=\"flag ' + (warn && on ? 'warn' : on ? 'on' : 'off') + '\">' + l + ': ' + (on ? 'on' : 'off') + '</span>';\n  const t = o.tourney;\n  main.innerHTML = '<h1>Overview</h1><div class=\"sub\">Cairo time · updated ' + when(Date.now()) + '</div>' +\n    '<div class=\"flags\">' + f(o.flags.prizes, 'Monthly prizes') + f(o.flags.maintenance, 'Maintenance', true) + f(!!o.flags.notice, 'Notice') + f(t.enabled, 'Tournament') + f(o.flags.season, 'Season pass') + f(o.flags.push, 'Push') + '</div>' +\n    '<div class=\"grid\">' +\n      k(num(o.live.online), 'Online now · ' + num(o.live.tables) + ' tables · ' + num(o.live.queued) + ' waiting') +\n      k(num(o.activeToday), 'Played today · ' + num(o.activeWeek) + ' this week') +\n      k(num(o.players), 'Players · ' + num(o.signedIn) + ' signed in · ' + num(o.newToday) + ' new today') +\n      k(num(o.gamesToday), 'Games today · fees ' + short(o.houseFeesToday) + ' coins') +\n      k(o.prizePending ? num(o.prizePending) + ' · ' + num(o.prizePendingEgp) + ' EGP' : '0', 'Prizes to pay · ' + num(o.prizeUnclaimed) + ' waiting for a number · ' + num(o.prizePaidEgp) + ' EGP paid in all', o.prizePending > 0) +\n      k(num(o.seasonPremium), 'Season pass buyers this month') +\n      k(num(o.purchasesToday) + ' / ' + num(o.purchasesWeek), 'Store purchases today / this week') +\n      k(short(o.coinsHeld), 'Coins held by players') +\n      k(num(o.reportsWeek), 'Player reports this week · ' + num(o.support) + ' support messages', o.reportsWeek > 20) +\n      k(num(o.banned), 'Banned players') +\n    '</div>' +\n    '<div class=\"grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(380px,1fr));margin-top:14px\">' +\n      '<div class=\"card\">' + bars(o.daily, 'active', 'Players who played', '#c9a25a') + '</div>' +\n      '<div class=\"card\">' + bars(o.daily, 'games', 'Games finished', '#4fae6a') + '</div>' +\n      '<div class=\"card\">' + bars(o.daily, 'newPlayers', 'New players', '#6f9fd8') + '</div>' +\n      '<div class=\"card\">' + bars(o.daily, 'prizeEgp', 'Prizes paid (EGP)', '#e0a03a') + '</div>' +\n    '</div>' +\n    '<h2>Next tournament</h2><div class=\"card row\" style=\"justify-content:space-between\"><div><b>' + esc(GAMES[t.game] || t.game) + '</b> · ' + esc(t.state) + ' · ' + when(t.startsAt) + '<div class=\"sub\">' + num(t.registered) + ' signed up</div></div><a class=\"btn\" href=\"#tourney\">Manage</a></div>' +\n    (o.flags.notice ? '<h2>Notice showing</h2><div class=\"card\">' + esc(o.flags.notice) + '</div>' : '');\n};\n\n/* ---------------- prize requests ---------------- */\nRENDER.prizes = async main => {\n  const status = (location.hash.split('/')[1]) || 'pending';\n  const d = await api('/prizes?status=' + status);\n  const rules = d.rules;\n  const pend = d.rows.filter(r => r.status === 'pending');\n  if (status === 'pending') setPending(pend.length);\n  const GN = { domino: 'Dominoes', tawla: 'Backgammon', chess: 'Chess', ludo: 'Ludo' };\n  const monthName = m => { const [y, mo] = m.split('-').map(Number); return new Date(Date.UTC(y, mo - 1, 15)).toLocaleString('en', { month: 'long', year: 'numeric' }); };\n  const LABEL = { pending: 'To pay', unclaimed: 'Waiting for a number', paid: 'Paid', rejected: 'Rejected', expired: 'Expired', all: 'All' };\n  main.innerHTML = '<h1>Monthly prizes · Vodafone Cash</h1>' +\n    '<div class=\"sub\">On the 1st of each month, the top player of each game\\'s monthly leaderboard (at least ' + d.minGames + ' online games) wins <b>' + num(rules.egp) + ' EGP</b> and the \"player of the month\" title. ' +\n      'The winner enters a Vodafone Cash number (' + esc(rules.prefixes.join(', ')) + ') in the game within ' + rules.claimDays + ' days. Prizes are <b>' + (rules.enabled ? 'on' : 'off') + '</b> (<a href=\"#settings\">change</a>) · this month\\'s race is on the <a href=\"#titles\">Titles</a> page.</div>' +\n    '<div class=\"tabs\">' + Object.keys(LABEL).map(s => '<button data-s=\"' + s + '\" class=\"' + (s === status ? 'on' : '') + '\">' + LABEL[s] + '</button>').join('') + '</div>' +\n    (status === 'pending' && pend.length ? '<div class=\"card\" style=\"margin-bottom:12px\">To pay: <b>' + pend.length + '</b> · <b>' + num(pend.reduce((a, r) => a + r.egp, 0)) + ' EGP</b>. Send the money on Vodafone Cash, then press <b>Paid</b> (the winner gets a notification). <b>Ask again</b> if the number is wrong; <b>Reject</b> if the win broke the rules (cheating, several accounts).</div>' : '') +\n    (d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>Month</th><th>Game</th><th>Winner</th><th>Vodafone Cash</th><th class=\"num\">EGP</th><th>Status</th><th></th></tr></thead><tbody>' +\n      d.rows.map(r => '<tr><td class=\"mono\">' + r.id + '</td><td>' + esc(monthName(r.month)) + '</td><td>' + esc(GN[r.game] || r.game) + '</td><td><a href=\"#players/' + esc(r.user_id) + '\" data-player=\"' + esc(r.user_id) + '\">' + esc(r.name || '—') + '</a><div class=\"sub\">won ' + when(r.ts) + '</div></td>' +\n        '<td>' + (r.phone ? '<b class=\"mono\" style=\"font-size:14px\">' + esc(r.phone) + '</b> <button class=\"btn sm\" data-copy=\"' + esc(r.phone) + '\">Copy</button>' : '<span class=\"muted\">not given yet</span>') + '</td><td class=\"num\"><b>' + num(r.egp) + '</b></td>' +\n        '<td><span class=\"tag ' + (r.status === 'unclaimed' ? '' : r.status === 'expired' ? 'rejected' : r.status) + '\">' + (LABEL[r.status] || r.status) + '</span>' + (r.done_ts ? '<div class=\"sub\">' + when(r.done_ts) + '</div>' : '') + (r.note ? '<div class=\"sub\">' + esc(r.note) + '</div>' : '') + '</td>' +\n        '<td>' + (r.status === 'pending' ? '<div class=\"row\"><button class=\"btn sm ok\" data-pay=\"' + r.id + '\" data-egp=\"' + r.egp + '\" data-phone=\"' + esc(r.phone) + '\">Paid</button><button class=\"btn sm\" data-again=\"' + r.id + '\">Ask again</button><button class=\"btn sm bad\" data-rej=\"' + r.id + '\">Reject</button></div>'\n          : r.status === 'unclaimed' ? '<button class=\"btn sm bad\" data-rej=\"' + r.id + '\">Reject</button>' : '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">Nothing here</div>');\n  main.querySelectorAll('[data-s]').forEach(b => b.onclick = () => { location.hash = 'prizes/' + b.dataset.s; });\n  main.querySelectorAll('[data-copy]').forEach(b => b.onclick = () => { navigator.clipboard.writeText(b.dataset.copy); toast('Copied ' + b.dataset.copy); });\n  const settle = (id, action, note, ok) => act(() => api('/prizes/' + id, { body: { action, note } }), ok).then(go);\n  main.querySelectorAll('[data-pay]').forEach(b => b.onclick = () => { const note = prompt('Sent ' + b.dataset.egp + ' EGP to ' + b.dataset.phone + '?\\nTransaction number (optional):', ''); if (note !== null) settle(b.dataset.pay, 'paid', note, 'Marked paid · the winner was told'); });\n  main.querySelectorAll('[data-again]').forEach(b => b.onclick = () => { const note = prompt('Ask the winner for their number again?\\nWhat was wrong (they see it):', 'الرقم مش على فودافون كاش'); if (note !== null) settle(b.dataset.again, 'again', note, 'The winner was asked again'); });\n  main.querySelectorAll('[data-rej]').forEach(b => b.onclick = () => { const note = prompt('Reject this prize for good?\\nReason (the winner sees it):', ''); if (note !== null) settle(b.dataset.rej, 'reject', note, 'Rejected'); });\n  main.querySelectorAll('[data-player]').forEach(a => a.onclick = e => { e.preventDefault(); openPlayer(a.dataset.player); });\n};\n\n/* ---------------- players ---------------- */\nRENDER.players = async main => {\n  const parts = location.hash.split('/'), open = parts[1];\n  main.innerHTML = '<h1>Players</h1><div class=\"sub\">Search by name, friend code, player id, e-mail or phone</div>' +\n    '<form id=\"sf\" class=\"row\" style=\"margin:12px 0\"><input id=\"sq\" placeholder=\"Search players\" style=\"min-width:280px\" value=\"' + esc(state.q || '') + '\"><button class=\"btn gold\">Search</button></form><div id=\"pl\"></div>';\n  const load = async () => {\n    const d = await api('/players?q=' + encodeURIComponent(state.q || ''));\n    $('#pl').innerHTML = d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>Player</th><th>Sign-in</th><th class=\"num\">Coins</th><th class=\"num\">Games</th><th class=\"num\">Win %</th><th>Joined</th><th>Last seen</th><th></th></tr></thead><tbody>' +\n      d.rows.map(u => '<tr class=\"click\" data-id=\"' + esc(u.id) + '\"><td><b>' + esc(u.name) + '</b>' + (u.online ? ' <span class=\"tag on\">online</span>' : '') + (u.banned ? ' <span class=\"tag banned\">banned</span>' : '') + (u.muted ? ' <span class=\"tag\">muted</span>' : '') +\n        '<div class=\"sub mono\">' + esc(u.code || u.pid || u.id) + '</div></td><td><span class=\"tag ' + u.login + '\">' + u.login + '</span><div class=\"sub\">' + esc(u.contact) + '</div></td>' +\n        '<td class=\"num\">' + short(u.coins) + '</td><td class=\"num\">' + num(u.games) + '</td><td class=\"num\">' + (u.games ? Math.round(u.wins / u.games * 100) : 0) + '%</td><td>' + when(u.created) + '</td><td>' + ago(u.seen) + '</td><td>›</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No players found</div>';\n    $('#pl').querySelectorAll('tr[data-id]').forEach(tr => tr.onclick = () => openPlayer(tr.dataset.id));\n  };\n  $('#sf').onsubmit = e => { e.preventDefault(); state.q = $('#sq').value; load(); };\n  await load();\n  if (open) openPlayer(open);\n};\n\nasync function openPlayer(id) {\n  closeDrawer();\n  const sh = document.createElement('div'); sh.className = 'shade'; sh.onclick = closeDrawer;\n  const dr = document.createElement('div'); dr.className = 'drawer'; dr.innerHTML = '<div class=\"empty\">Loading…</div>';\n  document.body.append(sh, dr);\n  const render = async () => {\n    const d = await api('/players/' + encodeURIComponent(id));\n    const u = d.user, s = d.stats || {}, r = d.row;\n    const skins = state.catalog.skins.filter(k => !k.free && !d.skins.includes(k.id));\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + esc(u.name) + '</h1>' + (d.title ? '<div style=\"margin:4px 0 6px\">' + badge(titleById(d.title), 'en') + '</div>' : '') +\n      '<div class=\"sub mono\">' + esc(u.id) + ' · code ' + esc(r.code || '—') + ' · ' + r.login + (r.contact ? ' · ' + esc(r.contact) : '') + '</div>' +\n      '<div class=\"flags\">' + (d.online ? '<span class=\"flag on\">online</span>' : '<span class=\"flag off\">last seen ' + ago(u.seen) + '</span>') + (r.banned ? '<span class=\"flag warn\">banned: ' + esc(u.ban_reason || '') + '</span>' : '') + (r.muted ? '<span class=\"flag warn\">muted</span>' : '') + (d.season.premium ? '<span class=\"flag on\">season premium</span>' : '') + '</div>' +\n      '<div class=\"grid\">' +\n        '<div class=\"card kpi\"><div class=\"v\">' + num(u.coins) + '</div><div class=\"l\">Coins</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + num(s.games) + '</div><div class=\"l\">Games · ' + num(s.wins) + ' won · ' + (s.winRate || 0) + '%</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + short(s.net) + '</div><div class=\"l\">Net from games · won ' + short(s.coinsWon) + ' / lost ' + short(s.coinsLost) + '</div></div>' +\n        '<div class=\"card kpi\"><div class=\"v\">' + (s.level || 1) + '</div><div class=\"l\">Level · season tier ' + d.season.tier + ' (' + d.season.sp + ' SP)</div></div>' +\n      '</div>' +\n      '<h2>Actions</h2><div class=\"card\" style=\"display:grid;gap:10px\">' +\n        '<div class=\"row\"><input id=\"pc\" type=\"number\" placeholder=\"Coins (− takes)\" style=\"width:170px\"><input id=\"pr\" placeholder=\"Reason (log)\"><button class=\"btn gold\" id=\"bc\">Give / take coins</button></div>' +\n        '<div class=\"row\"><select id=\"ps\"><option value=\"\">Give a skin…</option>' + skins.map(k => '<option value=\"' + k.id + '\">' + esc(k.cat + ' · ' + k.id) + (k.pass ? ' (season)' : '') + '</option>').join('') + '</select><button class=\"btn\" id=\"bs\">Give skin</button>' +\n          '<button class=\"btn\" id=\"bp\">' + (d.season.premium ? 'Remove season premium' : 'Give season premium') + '</button><input id=\"psp\" type=\"number\" placeholder=\"Season points\" value=\"' + d.season.sp + '\"><button class=\"btn\" id=\"bsp\">Set SP</button></div>' +\n        '<div class=\"row\"><input id=\"pn\" placeholder=\"New name\" value=\"' + esc(u.name) + '\"><button class=\"btn\" id=\"bn\">Rename</button>' +\n          (r.muted ? '<button class=\"btn\" id=\"bum\">Unmute</button>' : '<button class=\"btn\" id=\"bm\">Mute 24 h</button>') +\n          (r.banned ? '<button class=\"btn ok\" id=\"bub\">Unban</button>' : '<button class=\"btn bad\" id=\"bb\">Ban</button>') + '</div>' +\n        '<div class=\"row\"><input id=\"pt\" placeholder=\"Push title\" style=\"width:180px\"><input id=\"px\" placeholder=\"Push message to this player\" style=\"flex:1;min-width:220px\"><button class=\"btn\" id=\"bx\">Send</button></div>' +\n        '<div class=\"row\"><button class=\"btn bad sm\" id=\"bd\">Delete account</button><span class=\"sub\">Removes the player and everything they have. Can\\'t be undone.</span></div>' +\n      '</div>' +\n      '<h2>Coin history</h2>' + (d.coins.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>What</th><th class=\"num\">Change</th><th class=\"num\">Balance</th></tr></thead><tbody>' +\n        d.coins.map(c => '<tr><td>' + when(c.ts) + '</td><td>' + esc(c.kind) + (c.mode ? ' · ' + esc(c.mode) : '') + (c.stake ? ' · stake ' + short(c.stake) : '') + '</td><td class=\"num\" style=\"color:' + (c.delta >= 0 ? '#9fe0b0' : '#ff9d92') + '\">' + (c.delta >= 0 ? '+' : '') + num(c.delta) + '</td><td class=\"num\">' + num(c.balance) + '</td></tr>').join('') + '</tbody></table></div>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Monthly prizes</h2>' + (d.prizes.length ? '<table><tbody>' + d.prizes.map(c => '<tr><td>#' + c.id + '</td><td>' + esc(c.month) + ' · ' + esc(c.game) + '</td><td class=\"mono\">' + esc(c.phone || '—') + '</td><td class=\"num\">' + num(c.egp) + ' EGP</td><td><span class=\"tag ' + c.status + '\">' + c.status + '</span></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Purchases</h2>' + (d.purchases.length ? '<table><tbody>' + d.purchases.map(p => '<tr><td>' + when(p.ts) + '</td><td>' + esc(p.product) + '</td><td class=\"mono\">' + esc(p.order_id || '') + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>') +\n      '<h2>Skins (' + d.skins.length + ')</h2><div class=\"card\">' + (d.skins.map(k => '<span class=\"tag\" style=\"margin:2px\">' + esc(k) + ' <a href=\"#\" data-unskin=\"' + esc(k) + '\" title=\"Take back\">✕</a></span>').join('') || '<span class=\"muted\">Only the free ones</span>') + '</div>' +\n      '<h2>Titles</h2><div class=\"card\" style=\"display:grid;gap:10px\">' + (d.titles.length ? '<div class=\"row\">' + d.titles.map(t => '<span>' + badge(titleById(t.id), 'en') + (d.title === t.id ? ' <span class=\"tag on\">wearing</span>' : '') + (t.until ? ' <span class=\"sub\">until ' + when(t.until) + '</span>' : '') + ' <a href=\"#\" data-untitle=\"' + esc(t.id) + '\" title=\"Take back\">✕</a></span>').join('') + '</div>' : '<span class=\"muted\">No titles</span>') +\n        '<div class=\"row\"><select id=\"pti\"><option value=\"\">Give a title…</option>' + state.catalog.titles.filter(t => !t.monthly).map(t => '<option value=\"' + t.id + '\">' + esc(t.en + ' · ' + t.ar) + '</option>').join('') + '</select><select id=\"ptd\"><option value=\"0\">for good</option><option value=\"7\">7 days</option><option value=\"30\">30 days</option><option value=\"90\">90 days</option></select><button class=\"btn\" id=\"bti\">Give title</button></div></div>' +\n      '<h2>Reports about this player (' + d.reportsAbout.length + ')</h2>' + (d.reportsAbout.length ? '<table><tbody>' + d.reportsAbout.map(x => '<tr><td>' + when(x.ts) + '</td><td>' + esc(x.reason) + '</td><td>by ' + esc(x.from_name || x.from_id) + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None</div>');\n    const post = (body, ok) => act(() => api('/players/' + encodeURIComponent(id), { body }), ok).then(render);\n    $('#cx', dr).onclick = closeDrawer;\n    $('#bc', dr).onclick = () => { const a = Number($('#pc', dr).value); if (!a) return toast('Enter an amount', true); if (Math.abs(a) >= 10000000 && !confirm('That is ' + num(a) + ' coins. Sure?')) return; post({ action: 'coins', amount: a, reason: $('#pr', dr).value }, (a > 0 ? 'Gave ' : 'Took ') + num(Math.abs(a)) + ' coins'); };\n    $('#bs', dr).onclick = () => { const k = $('#ps', dr).value; if (k) post({ action: 'skin', skin: k }, 'Skin given'); };\n    $('#bp', dr).onclick = () => post({ action: d.season.premium ? 'unpremium' : 'premium' }, 'Season pass updated');\n    $('#bsp', dr).onclick = () => post({ action: 'sp', sp: Number($('#psp', dr).value) }, 'Season points set');\n    $('#bn', dr).onclick = () => post({ action: 'rename', name: $('#pn', dr).value }, 'Renamed');\n    if ($('#bm', dr)) $('#bm', dr).onclick = () => post({ action: 'mute', hours: 24 }, 'Muted for 24 h');\n    if ($('#bum', dr)) $('#bum', dr).onclick = () => post({ action: 'unmute' }, 'Unmuted');\n    if ($('#bb', dr)) $('#bb', dr).onclick = () => { const why = prompt('Ban ' + u.name + '? Reason (they see it):', ''); if (why !== null) post({ action: 'ban', reason: why }, 'Banned'); };\n    if ($('#bub', dr)) $('#bub', dr).onclick = () => post({ action: 'unban' }, 'Unbanned');\n    $('#bx', dr).onclick = () => { const t = $('#px', dr).value; if (t) post({ action: 'notify', title: $('#pt', dr).value, text: t }, 'Sent'); };\n    $('#bd', dr).onclick = () => { if (prompt('Type DELETE to delete ' + u.name + ' for good') === 'DELETE') act(() => api('/players/' + encodeURIComponent(id), { body: { action: 'delete' } }), 'Deleted').then(() => { closeDrawer(); go(); }); };\n    $('#bti', dr).onclick = () => { const k = $('#pti', dr).value; if (k) post({ action: 'title', title: k, days: Number($('#ptd', dr).value) }, 'Title given'); };\n    dr.querySelectorAll('[data-untitle]').forEach(a => a.onclick = e => { e.preventDefault(); if (confirm('Take back this title?')) post({ action: 'untitle', title: a.dataset.untitle }, 'Title taken back'); });\n    dr.querySelectorAll('[data-unskin]').forEach(a => a.onclick = e => { e.preventDefault(); if (confirm('Take back ' + a.dataset.unskin + '?')) post({ action: 'unskin', skin: a.dataset.unskin }, 'Skin taken back'); });\n  };\n  try { await render(); } catch (e) { dr.innerHTML = '<button class=\"btn sm x\" onclick=\"closeDrawer()\">Close ✕</button><div class=\"card\">' + esc(e.message) + '</div>'; }\n}\nfunction closeDrawer() { document.querySelectorAll('.drawer,.shade').forEach(x => x.remove()); }\ndocument.addEventListener('keydown', e => { if (e.key === 'Escape') closeDrawer(); });\n\n/* ---------------- rewards and notices ---------------- */\nRENDER.rewards = async main => {\n  const st = await api('/settings');\n  const live = st.notice.until > Date.now() && st.notice.text;\n  main.innerHTML = '<h1>Rewards & notices</h1>' +\n    '<h2>Coins for everyone</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Coins each<input id=\"gc\" type=\"number\" min=\"1\" placeholder=\"e.g. 50000\"></label>' +\n      '<label class=\"f\">Who<select id=\"ga\"><option value=\"7\">Played in the last 7 days</option><option value=\"30\">Played in the last 30 days</option><option value=\"0\">Every player</option></select></label>' +\n      '<label class=\"f\" style=\"grid-column:1/-1\">Message (shown in the game and as a push)<input id=\"gm\" placeholder=\"هدية بمناسبة… · A gift for…\"></label>' +\n    '</div><div class=\"row\" style=\"margin-top:12px\"><label class=\"switch\"><input type=\"checkbox\" id=\"gp\" checked> Send a push notification</label><button class=\"btn gold\" id=\"gb\">Send the gift</button></div></div>' +\n    '<h2>Notice in the game</h2><div class=\"card\"><div class=\"sub\" style=\"margin-bottom:8px\">Shown to every player when they open the game (and right away to those playing now). ' + (live ? 'Showing now until ' + when(st.notice.until) + '.' : 'Nothing showing.') + '</div>' +\n      '<div class=\"form\"><label class=\"f\" style=\"grid-column:1/-1\">Text<textarea id=\"nt\" rows=\"2\" maxlength=\"400\">' + esc(live ? st.notice.text : '') + '</textarea></label>' +\n      '<label class=\"f\">Show for (hours)<input id=\"nh\" type=\"number\" value=\"24\" min=\"1\" max=\"720\"></label></div>' +\n      '<div class=\"row\" style=\"margin-top:12px\"><label class=\"switch\"><input type=\"checkbox\" id=\"np\"> Also a push to players of the last 30 days</label><button class=\"btn gold\" id=\"nb\">Show notice</button>' + (live ? '<button class=\"btn\" id=\"nc\">Take it down</button>' : '') + '</div></div>' +\n    '<h2>Daily reward, ads and weekly prizes</h2><div class=\"card\"><div class=\"sub\">Daily streak: ' + st.economy.streak.map(short).join(' · ') + ' · rewarded ad: ' + short(st.economy.adReward) + ' (' + st.economy.adsPerDay + ' a day) · weekly top ten: ' + st.economy.weeklyPrizes.map(short).join(' · ') + '</div><a class=\"btn\" href=\"#settings\" style=\"display:inline-block;margin-top:10px\">Change them</a></div>';\n  $('#gb').onclick = async () => {\n    const c = Number($('#gc').value), days = Number($('#ga').value);\n    if (!(c > 0)) return toast('Enter the coins', true);\n    if (!confirm('Give ' + num(c) + ' coins to ' + (days ? 'everyone who played in the last ' + days + ' days' : 'every player') + '?')) return;\n    const r = await act(() => api('/rewards', { body: { coins: c, activeDays: days, message: $('#gm').value, push: $('#gp').checked } }));\n    toast('Sent to ' + num(r.players) + ' players');\n  };\n  $('#nb').onclick = async () => { await act(() => api('/notice', { body: { text: $('#nt').value, hours: Number($('#nh').value), push: $('#np').checked } }), 'Notice is showing'); go(); };\n  if ($('#nc')) $('#nc').onclick = async () => { await act(() => api('/notice', { body: { text: '' } }), 'Notice taken down'); go(); };\n};\n\n/* ---------------- tournaments ---------------- */\nRENDER.tourney = async main => {\n  const d = await api('/tourney'), v = d.view, t = d.settings;\n  const who = e => e ? esc(e.name) + (e.bot ? ' <span class=\"muted\">(cpu)</span>' : '') : '<span class=\"muted\">—</span>';\n  main.innerHTML = '<h1>Tournaments</h1>' +\n    '<div class=\"card row\" style=\"justify-content:space-between\"><div><b>' + esc(GAMES[v.game] || v.game) + '</b> · <span class=\"tag ' + (v.state === 'running' ? 'pending' : '') + '\">' + v.state + '</span> · starts ' + when(v.startsAt) +\n      '<div class=\"sub\">' + num(v.count) + (v.state === 'open' ? ' signed up' : ' places in the bracket') + ' · prizes ' + v.prizes.map(short).join(' · ') + '</div></div>' +\n      '<div class=\"row\">' + (v.state === 'open' ? '<button class=\"btn gold\" id=\"ts\">Start now</button>' : '') + (v.state !== 'done' ? '<button class=\"btn bad\" id=\"tc\">' + (v.state === 'running' ? 'Stop' : 'Skip this one') + '</button>' : '') + '</div></div>' +\n    (v.rounds.length ? '<h2>Bracket</h2><div class=\"bracket\">' + v.rounds.map((r, i) => '<div class=\"round\"><div class=\"sub\">' + (i === v.rounds.length - 1 ? 'Final' : i === v.rounds.length - 2 ? 'Semi-finals' : 'Round ' + (i + 1)) + '</div>' +\n      r.map(m => '<div class=\"match\"><div class=\"' + (m.winner === 0 ? 'w' : '') + '\">' + who(m.a) + '</div><div class=\"' + (m.winner === 1 ? 'w' : '') + '\">' + who(m.b) + '</div>' + (m.live ? '<div class=\"sub\">playing…</div>' : '') + '</div>').join('') + '</div>').join('') + '</div>' : '') +\n    (v.results.length ? '<h2>Results</h2><table><tbody>' + v.results.map(x => '<tr><td>#' + x.place + '</td><td>' + esc(x.name) + '</td><td class=\"num\">' + num(x.coins) + '</td></tr>').join('') + '</tbody></table>' : '') +\n    '<h2>Settings</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Tournaments in the game<span class=\"switch\"><input type=\"checkbox\" id=\"te\"' + (t.enabled ? ' checked' : '') + '> on (off: hidden in the game, none start)</span></label>' +\n      '<label class=\"f\">Day (Cairo)<select id=\"tw\">' + DAYS.map((x, i) => '<option value=\"' + i + '\"' + (i === t.weekday ? ' selected' : '') + '>' + x + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">Hour (0–23, Cairo)<input id=\"th\" type=\"number\" min=\"0\" max=\"23\" value=\"' + t.hour + '\"></label>' +\n      '<label class=\"f\">Game<select id=\"tg\">' + Object.entries(GAMES).map(([k, l]) => '<option value=\"' + k + '\"' + (k === t.game ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n      t.prizes.map((p, i) => '<label class=\"f\">Prize #' + (i + 1) + (i >= 4 ? ' (5th–8th)' : '') + '<input type=\"number\" min=\"0\" class=\"tp\" value=\"' + p + '\"></label>').join('') +\n      '<label class=\"f\">Everyone who played<input id=\"tpl\" type=\"number\" min=\"0\" value=\"' + t.played + '\"></label>' +\n    '</div><button class=\"btn gold\" id=\"tsv\" style=\"margin-top:12px\">Save tournament settings</button></div>' +\n    '<h2>Signed up (' + d.registered.length + ')</h2>' + (d.registered.length ? '<div class=\"card\">' + d.registered.map(r => '<a href=\"#players/' + esc(r.id) + '\" class=\"tag\" style=\"margin:2px;text-decoration:none\">' + esc(r.name) + (r.online ? ' ●' : '') + '</a>').join('') + '</div>' : '<div class=\"card empty\">Nobody yet</div>') +\n    '<h2>Past tournaments</h2>' + (d.history.length ? '<table><thead><tr><th>Date</th><th>Game</th><th class=\"num\">People</th><th>Winner</th><th>2nd</th></tr></thead><tbody>' +\n      d.history.map(h => '<tr><td>' + esc(h.event) + '</td><td>' + esc(GAMES[h.game] || h.game) + '</td><td class=\"num\">' + num(h.people) + '</td><td>' + esc(h.results?.[0]?.name || '—') + '</td><td>' + esc(h.results?.[1]?.name || '—') + '</td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">None yet</div>');\n  if ($('#ts')) $('#ts').onclick = async () => { if (confirm('Start the tournament now with ' + v.count + ' players?')) { await act(() => api('/tourney', { body: { action: 'start' } }), 'Started'); go(); } };\n  if ($('#tc')) $('#tc').onclick = async () => { if (confirm(v.state === 'running' ? 'Stop the running tournament? Nobody is paid.' : 'Skip this tournament and open the next one?')) { await act(() => api('/tourney', { body: { action: 'cancel' } }), 'Done'); go(); } };\n  $('#tsv').onclick = async () => {\n    await act(() => api('/settings', { method: 'PUT', body: { tourney: { enabled: $('#te').checked, weekday: Number($('#tw').value), hour: Number($('#th').value), game: $('#tg').value,\n      prizes: [...main.querySelectorAll('.tp')].map(i => Number(i.value)), played: Number($('#tpl').value) } } }), 'Tournament settings saved'); go();\n  };\n};\n\n/* ---------------- season pass ---------------- */\nRENDER.season = async main => {\n  const d = await api('/season'), st = d.settings;\n  const skinOpts = (sel, coins) => (coins ? '<option value=\"\">— coins —</option>' : '') + d.skins.map(k => '<option value=\"' + k.id + '\"' + (k.id === sel ? ' selected' : '') + '>' + esc(k.cat + ' · ' + k.id) + (k.pass ? ' ★' : '') + '</option>').join('');\n  const cell = (rw, track, i) => '<div class=\"row\" style=\"gap:6px\"><select class=\"rk\" data-t=\"' + track + '\" data-i=\"' + i + '\">' + skinOpts(rw.skin, track === 'free') + '</select><input type=\"number\" class=\"rc\" data-t=\"' + track + '\" data-i=\"' + i + '\" value=\"' + (rw.coins ?? '') + '\" placeholder=\"coins\" style=\"width:110px' + (rw.skin || track === 'prem' ? ';display:none' : '') + '\"></div>';\n  const max = Math.max(1, ...d.tiers);\n  main.innerHTML = '<h1>Season pass</h1><div class=\"sub\">Season ' + esc(d.season) + ' · ends ' + when(d.endsAt) + '</div>' +\n    '<div class=\"card row\" style=\"justify-content:space-between;margin-top:12px' + (st.enabled ? '' : ';border-color:var(--warn)') + '\"><label class=\"switch\"><input type=\"checkbox\" id=\"sen\"' + (st.enabled ? ' checked' : '') + '> <b>Season pass in the game</b></label>' +\n      '<span class=\"sub\">' + (st.enabled ? 'On: players earn season points, collect rewards and can buy premium.' : 'Off: hidden in the game; no points, rewards or premium sales. Players who already bought premium keep it (and no ads).') + '</span></div>' +\n    '<div class=\"grid\" style=\"margin-top:12px\">' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.players) + '</div><div class=\"l\">Players on the track</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.premium) + '</div><div class=\"l\">With premium (' + (d.players ? Math.round(d.premium / d.players * 100) : 0) + '%)</div></div>' +\n      '<div class=\"card kpi\"><div class=\"v\">' + num(d.paidPlay) + '</div><div class=\"l\">Bought on Google Play (40 days)</div></div>' +\n    '</div>' +\n    '<h2>How far players got</h2><div class=\"card\"><svg class=\"chart\" viewBox=\"0 0 640 140\" style=\"max-height:200px\">' + d.tiers.map((n, i) => { const h = Math.round(n / max * 100), x = 12 + i * 20; return '<rect x=\"' + x + '\" y=\"' + (110 - h) + '\" width=\"15\" height=\"' + Math.max(1, h) + '\" rx=\"2\" fill=\"#c9a25a\"><title>Tier ' + i + ': ' + n + '</title></rect>' + (i % 5 === 0 ? '<text x=\"' + (x + 7) + '\" y=\"128\" fill=\"#b9a88a\" font-size=\"10\" text-anchor=\"middle\">' + i + '</text>' : ''); }).join('') + '</svg></div>' +\n    '<h2>Price</h2><div class=\"card\"><div class=\"form\"><label class=\"f\">Premium with coins<input id=\"sc\" type=\"number\" value=\"' + st.passCoins + '\"></label>' +\n      '<label class=\"f\">Premium price shown (EGP)<input id=\"se\" type=\"number\" value=\"' + st.passEgp + '\"></label></div>' +\n      '<div class=\"sub\" style=\"margin-top:8px\">The price players actually pay on Google Play is set in Play Console (product <span class=\"mono\">season_pass</span>); keep the two the same.</div></div>' +\n    '<h2>Rewards per tier</h2><div class=\"sub\">Free track: a skin or coins. Premium track: skins only (premium also removes ads until the season ends). ★ = only from the season.</div>' +\n    '<div class=\"tablewrap\"><table><thead><tr><th>Tier</th><th>Free track</th><th>Premium track</th></tr></thead><tbody>' +\n      st.tiers.map((t, i) => '<tr class=\"tierrow\"><td><b>' + (i + 1) + '</b></td><td>' + cell(t.free, 'free', i) + '</td><td>' + cell(t.prem, 'prem', i) + '</td></tr>').join('') +\n    '</tbody></table></div><button class=\"btn gold\" id=\"ssv\" style=\"margin-top:12px\">Save the season pass</button>';\n  $('#sen').onchange = async e => {\n    const on = e.target.checked;\n    if (!confirm(on ? 'Show the season pass in the game again?' : 'Switch the season pass off? It disappears from the game for everyone.')) { e.target.checked = !on; return; }\n    await act(() => api('/settings', { method: 'PUT', body: { season: { enabled: on } } }), on ? 'Season pass is on' : 'Season pass is off'); go();\n  };\n  main.querySelectorAll('.rk').forEach(s => s.onchange = () => { const c = main.querySelector('.rc[data-t=\"' + s.dataset.t + '\"][data-i=\"' + s.dataset.i + '\"]'); c.style.display = s.value ? 'none' : ''; });\n  $('#ssv').onclick = async () => {\n    const tiers = st.tiers.map((_, i) => {\n      const one = tr => { const k = main.querySelector('.rk[data-t=\"' + tr + '\"][data-i=\"' + i + '\"]').value; return k ? { skin: k } : { coins: Number(main.querySelector('.rc[data-t=\"' + tr + '\"][data-i=\"' + i + '\"]').value) || 0 }; };\n      return { free: one('free'), prem: one('prem') };\n    });\n    await act(() => api('/settings', { method: 'PUT', body: { season: { passCoins: Number($('#sc').value), passEgp: Number($('#se').value), tiers } } }), 'Season pass saved'); go();\n  };\n};\n\n/* ---------------- titles ---------------- */\nconst GNAME = { domino: 'Dominoes', tawla: 'Backgammon', chess: 'Chess', ludo: 'Ludo' };\nRENDER.titles = async main => {\n  const d = await api('/titles');\n  state.catalog.titles = d.list; state.catalog.icons = d.icons;\n  const cfg = d.settings;\n  const monthName = m => { const [y, mo] = m.split('-').map(Number); return new Date(Date.UTC(y, mo - 1, 15)).toLocaleString('en', { month: 'long', year: 'numeric' }); };\n  main.innerHTML = '<h1>Titles</h1><div class=\"sub\">A title shows under the player\\'s name: on their card, at their seat at the table and on the leaderboard. Players pick which of theirs to wear in Collection → Titles.</div>' +\n    '<h2>Player of the month</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Given by itself<span class=\"switch\"><input type=\"checkbox\" id=\"mo\"' + (cfg.monthly ? ' checked' : '') + '> on the 1st of each month</span></label>' +\n      '<label class=\"f\">Online games needed in the month<input id=\"mg\" type=\"number\" min=\"0\" value=\"' + cfg.minGames + '\"></label></div>' +\n      '<div class=\"sub\" style=\"margin:10px 0\">When a month ends, the player with the most points in each game (3 a win, 1 a game, online games only) gets that game\\'s title for the whole next month.</div>' +\n      '<button class=\"btn gold\" id=\"ms\">Save</button></div>' +\n    '<h2>The race this month · ' + esc(monthName(d.month)) + '</h2><div class=\"grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(250px,1fr))\">' +\n      Object.entries(d.race).map(([g, rows]) => '<div class=\"card\"><div style=\"margin-bottom:8px\">' + badge(d.list.find(t => t.monthly === g), 'en') + '</div>' +\n        (rows.length ? '<table><tbody>' + rows.map((r, i) => '<tr><td>#' + (i + 1) + '</td><td><a href=\"#players/' + esc(r.id) + '\">' + esc(r.name) + '</a>' + (r.games < cfg.minGames ? ' <span class=\"muted\">(needs ' + (cfg.minGames - r.games) + ' more games)</span>' : '') + '</td><td class=\"num\">' + r.points + ' pts</td></tr>').join('') + '</tbody></table>' : '<div class=\"muted\">No games yet this month</div>') + '</div>').join('') + '</div>' +\n    (d.winners.length ? '<h2>Past winners</h2><table><thead><tr><th>Month</th>' + Object.keys(GNAME).map(g => '<th>' + GNAME[g] + '</th>').join('') + '</tr></thead><tbody>' +\n      d.winners.map(w => '<tr><td>' + esc(monthName(w.month)) + '</td>' + Object.keys(GNAME).map(g => { const x = w.rows.find(r => r.game === g); return '<td>' + (x ? '<a href=\"#players/' + esc(x.uid) + '\">' + esc(x.name) + '</a>' : '<span class=\"muted\">—</span>') + '</td>'; }).join('') + '</tr>').join('') + '</tbody></table>' : '') +\n    '<h2 class=\"row\" style=\"justify-content:space-between\">All titles (' + d.list.length + ')<button class=\"btn gold\" id=\"tn\">+ New title</button></h2>' +\n    '<div class=\"tgrid\">' + d.list.map(t => '<div class=\"card tcard\"><div class=\"pv\">' + badge(t, 'ar', true) + badge(t, 'en') + '</div>' +\n      '<div class=\"sub\">' + (t.monthly ? 'Given each month to the best ' + GNAME[t.monthly] + ' player · ' : '') + (d.counts[t.id] || 0) + ((d.counts[t.id] || 0) === 1 ? ' player has' : ' players have') + ' it now · effect: ' + esc(t.style.effect) + '</div>' +\n      '<div class=\"row\"><button class=\"btn sm\" data-edit=\"' + t.id + '\">Edit design</button>' + (t.monthly ? '' : '<button class=\"btn sm gold\" data-give=\"' + t.id + '\">Give to a player</button>') +\n      '<button class=\"btn sm\" data-hold=\"' + t.id + '\">Who has it</button>' + (t.monthly ? '' : '<button class=\"btn sm bad\" data-del=\"' + t.id + '\">Delete</button>') + '</div></div>').join('') + '</div>';\n  $('#ms').onclick = async () => { await act(() => api('/settings', { method: 'PUT', body: { titles: { monthly: $('#mo').checked, minGames: Number($('#mg').value) } } }), 'Saved'); go(); };\n  $('#tn').onclick = () => titleEditor(null);\n  main.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => titleEditor(d.list.find(t => t.id === b.dataset.edit)));\n  main.querySelectorAll('[data-give]').forEach(b => b.onclick = () => titleGive(d.list.find(t => t.id === b.dataset.give)));\n  main.querySelectorAll('[data-hold]').forEach(b => b.onclick = () => titleHolders(d.list.find(t => t.id === b.dataset.hold)));\n  main.querySelectorAll('[data-del]').forEach(b => b.onclick = async () => { const t = d.list.find(x => x.id === b.dataset.del); if (confirm('Delete \"' + t.en + '\"? Everyone who has it loses it.')) { await act(() => api('/titles/' + t.id, { method: 'DELETE' }), 'Deleted'); go(); } });\n};\n\nfunction drawer() {\n  closeDrawer();\n  const sh = document.createElement('div'); sh.className = 'shade'; sh.onclick = closeDrawer;\n  const dr = document.createElement('div'); dr.className = 'drawer';\n  document.body.append(sh, dr);\n  return dr;\n}\n\nfunction titleEditor(t) {\n  const isNew = !t;\n  const cur = t ? structuredClone(t) : { id: '', ar: '', en: '', style: { bg: ['#f3cd62', '#b8862b'], fg: '#2a1a05', border: '#fff3c4', icon: 'crown', effect: 'shine' } };\n  const dr = drawer();\n  const icons = Object.keys(state.catalog.icons);\n  dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + (isNew ? 'New title' : 'Edit title') + '</h1>' +\n    '<div class=\"card\" style=\"display:grid;gap:12px;justify-items:center;padding:26px;margin:14px 0;background:#0d0805\"><div id=\"pv1\"></div><div id=\"pv2\"></div><div class=\"sub\">Preview: what players see</div></div>' +\n    '<div class=\"form\">' +\n      (isNew ? '<label class=\"f\">Id (english letters, no spaces)<input id=\"ti\" placeholder=\"e.g. night_owl\" maxlength=\"32\"></label>' : '') +\n      '<label class=\"f\">Arabic name<input id=\"tar\" dir=\"rtl\" maxlength=\"30\" value=\"' + esc(cur.ar) + '\"></label>' +\n      '<label class=\"f\">English name<input id=\"ten\" maxlength=\"30\" value=\"' + esc(cur.en) + '\"></label>' +\n    '</div><h2>Design</h2><div class=\"form\">' +\n      '<label class=\"f\">Background (start)<input type=\"color\" id=\"b0\" value=\"' + cur.style.bg[0] + '\"></label>' +\n      '<label class=\"f\">Background (end)<input type=\"color\" id=\"b1\" value=\"' + cur.style.bg[1] + '\"></label>' +\n      '<label class=\"f\">Text and icon<input type=\"color\" id=\"fg\" value=\"' + cur.style.fg + '\"></label>' +\n      '<label class=\"f\">Border<input type=\"color\" id=\"bd\" value=\"' + cur.style.border + '\"></label>' +\n      '<label class=\"f\">Effect<select id=\"fx\">' + [['none', 'None'], ['shine', 'Shine: a light sweeps across'], ['glow', 'Glow: the border breathes'], ['pulse', 'Pulse: beats gently']].map(([k, l]) => '<option value=\"' + k + '\"' + (k === cur.style.effect ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n    '</div><div class=\"sub\" style=\"margin:12px 0 6px\">Icon</div><div class=\"iconpick\">' + icons.map(k => '<button type=\"button\" data-ic=\"' + k + '\" title=\"' + k + '\" class=\"' + (k === cur.style.icon ? 'on' : '') + '\">' + (k === 'none' ? '∅' : iconSvg(k)) + '</button>').join('') + '</div>' +\n    '<div class=\"sub\" style=\"margin:14px 0 6px\">Quick looks</div><div class=\"row\" id=\"presets\"></div>' +\n    '<div class=\"row\" style=\"margin-top:18px\"><button class=\"btn gold\" id=\"tsv\">' + (isNew ? 'Create title' : 'Save') + '</button></div>';\n  const PRESETS = [['Gold', '#ffe08a', '#b8862b', '#2a1a05', '#fff6d6'], ['Emerald', '#11804f', '#063b25', '#ffd76a', '#ffd76a'], ['Royal', '#2c4bb0', '#0e1a4a', '#ffd76a', '#ffd76a'], ['Ruby', '#9c2430', '#4a0d14', '#ffd76a', '#ffd76a'],\n    ['Night', '#2b2b2b', '#0d0d0d', '#f3cd62', '#f3cd62'], ['Ice', '#18c3d6', '#0a5d8f', '#ffffff', '#c9f7ff'], ['Sunset', '#ff7a59', '#c2185b', '#ffffff', '#ffd1c2'], ['Wood', '#4a3526', '#1b120c', '#f4e6c8', '#c9a25a']];\n  $('#presets', dr).innerHTML = PRESETS.map((p, i) => '<button class=\"btn sm\" data-pre=\"' + i + '\" style=\"background:linear-gradient(90deg,' + p[1] + ',' + p[2] + ');color:' + p[3] + ';border-color:' + p[4] + '\">' + p[0] + '</button>').join('');\n  const read = () => ({ id: isNew ? $('#ti', dr).value.trim().toLowerCase() : cur.id, ar: $('#tar', dr).value, en: $('#ten', dr).value,\n    style: { bg: [$('#b0', dr).value, $('#b1', dr).value], fg: $('#fg', dr).value, border: $('#bd', dr).value, icon: cur.style.icon, effect: $('#fx', dr).value } });\n  const draw = () => { const v = read(); $('#pv1', dr).innerHTML = badge({ ...v, ar: v.ar || 'اسم اللقب' }, 'ar', true); $('#pv2', dr).innerHTML = badge({ ...v, en: v.en || 'Title name' }, 'en'); };\n  dr.querySelectorAll('input,select').forEach(i => i.oninput = draw);\n  dr.querySelectorAll('[data-ic]').forEach(b => b.onclick = () => { cur.style.icon = b.dataset.ic; dr.querySelectorAll('[data-ic]').forEach(x => x.classList.toggle('on', x === b)); draw(); });\n  dr.querySelectorAll('[data-pre]').forEach(b => b.onclick = () => { const p = PRESETS[b.dataset.pre]; $('#b0', dr).value = p[1]; $('#b1', dr).value = p[2]; $('#fg', dr).value = p[3]; $('#bd', dr).value = p[4]; draw(); });\n  $('#cx', dr).onclick = closeDrawer;\n  $('#tsv', dr).onclick = async () => {\n    const v = read();\n    if (!/^[a-z0-9_]{2,32}$/.test(v.id)) return toast('The id needs 2+ english letters, numbers or _', true);\n    if (!v.ar.trim() || !v.en.trim()) return toast('Write both names', true);\n    if (isNew && state.catalog.titles.some(t => t.id === v.id)) return toast('That id is taken', true);\n    await act(() => api('/titles', { method: 'PUT', body: v }), 'Saved · players see it at once'); closeDrawer(); go();\n  };\n  draw();\n}\n\nfunction titleGive(t, presetPlayer) {\n  const dr = drawer();\n  dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>Give a title</h1><div style=\"margin:10px 0 16px\">' + badge(t, 'ar', true) + ' ' + badge(t, 'en') + '</div>' +\n    '<div class=\"form\"><label class=\"f\">For how long<select id=\"gd\"><option value=\"0\">For good</option><option value=\"7\">7 days</option><option value=\"30\">30 days</option><option value=\"90\">90 days</option><option value=\"365\">A year</option></select></label>' +\n    '<label class=\"f\">Note (only here)<input id=\"gn\" maxlength=\"100\" placeholder=\"why\"></label></div>' +\n    '<label class=\"switch\" style=\"margin:10px 0\"><input type=\"checkbox\" id=\"gp\" checked> Tell the player (push notification)</label>' +\n    '<form id=\"gs\" class=\"row\" style=\"margin:10px 0\"><input id=\"gq\" placeholder=\"Find a player: name, code, e-mail, phone\" style=\"flex:1\"><button class=\"btn\">Search</button></form><div id=\"gr\"></div>';\n  $('#cx', dr).onclick = closeDrawer;\n  const give = async (id, name) => {\n    if (!confirm('Give \"' + t.en + '\" to ' + name + '?')) return;\n    await act(() => api('/players/' + encodeURIComponent(id), { body: { action: 'title', title: t.id, days: Number($('#gd', dr).value), note: $('#gn', dr).value, notify: $('#gp', dr).checked } }), name + ' has the title now');\n  };\n  $('#gs', dr).onsubmit = async e => {\n    e.preventDefault();\n    const r = await api('/players?q=' + encodeURIComponent($('#gq', dr).value));\n    $('#gr', dr).innerHTML = r.rows.length ? '<table><tbody>' + r.rows.slice(0, 20).map(u => '<tr><td><b>' + esc(u.name) + '</b><div class=\"sub mono\">' + esc(u.code || u.id) + '</div></td><td>' + esc(u.contact) + '</td><td><button class=\"btn sm gold\" data-g=\"' + esc(u.id) + '\" data-n=\"' + esc(u.name) + '\">Give</button></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">Nobody found</div>';\n    $('#gr', dr).querySelectorAll('[data-g]').forEach(b => b.onclick = () => give(b.dataset.g, b.dataset.n));\n  };\n}\n\nasync function titleHolders(t) {\n  const dr = drawer();\n  const draw = async () => {\n    const r = await api('/titles/' + t.id + '/holders');\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>Who has it</h1><div style=\"margin:10px 0 16px\">' + badge(t, 'en', true) + '</div>' +\n      (r.rows.length ? '<table><thead><tr><th>Player</th><th>Since</th><th>Until</th><th>Note</th><th></th></tr></thead><tbody>' + r.rows.map(h => '<tr><td><a href=\"#players/' + esc(h.id) + '\">' + esc(h.name) + '</a></td><td>' + when(h.ts) + '</td><td>' + (h.until ? when(h.until) : 'for good') + '</td><td>' + esc(h.note || '') + '</td><td><button class=\"btn sm bad\" data-rm=\"' + esc(h.id) + '\">Take back</button></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">Nobody has it now</div>');\n    $('#cx', dr).onclick = closeDrawer;\n    dr.querySelectorAll('[data-rm]').forEach(b => b.onclick = async () => { await act(() => api('/players/' + encodeURIComponent(b.dataset.rm), { body: { action: 'untitle', title: t.id } }), 'Taken back'); draw(); });\n  };\n  await draw();\n}\n\n/* ---------------- events: Ramadan, Eid and others ---------------- */\nconst EKIND = { ramadan: 'Ramadan', eid: 'Eid', custom: 'Other' };\n// rough dates: check them against the moon sighting before the event\nconst EPRESETS = [\n  { id: 'ramadan_2027', kind: 'ramadan', ar: 'رمضان كريم', en: 'Ramadan Kareem', from: '2027-02-07T18:00', to: '2027-03-09T18:00', spMult: 2, missionMult: 1.5, titleId: 'ramadan_lantern', titleGames: 30 },\n  { id: 'eid_fitr_2027', kind: 'eid', ar: 'عيد الفطر', en: 'Eid al-Fitr', from: '2027-03-09T18:00', to: '2027-03-13T00:00', spMult: 2, missionMult: 2, titleId: 'eid_joy', titleGames: 10 },\n  { id: 'eid_adha_2027', kind: 'eid', ar: 'عيد الأضحى', en: 'Eid al-Adha', from: '2027-05-15T18:00', to: '2027-05-20T00:00', spMult: 2, missionMult: 2, titleId: 'eid_joy', titleGames: 10 },\n];\nconst toLocal = ms => { const d = new Date(ms + 3 * 3600_000); return d.toISOString().slice(0, 16); };      // Cairo (UTC+3) for the inputs\nconst fromLocal = s => Date.parse(s + ':00Z') - 3 * 3600_000;\nRENDER.events = async main => {\n  const d = await api('/events'), now = Date.now();\n  const status = e => e.from <= now && now < e.to ? '<span class=\"tag on\">on now</span>' : now < e.from ? '<span class=\"tag pending\">coming</span>' : '<span class=\"tag\">over</span>';\n  main.innerHTML = '<h1>Events</h1><div class=\"sub\">Ramadan, Eid or anything else. While an event is on: season points and mission coins can be multiplied, players who play enough online games get its title, and its limited skins are in the shop (only then). The game shows a banner with what\\'s on. Times are Cairo time.</div>' +\n    '<h2 class=\"row\" style=\"justify-content:space-between\">Events (' + d.events.length + ')<span class=\"row\">' + EPRESETS.map((p, i) => '<button class=\"btn sm\" data-pre=\"' + i + '\">+ ' + esc(p.en) + ' 2027</button>').join('') + '<button class=\"btn gold sm\" id=\"enew\">+ New event</button></span></h2>' +\n    (d.events.length ? '<table><thead><tr><th>Event</th><th>When (Cairo)</th><th>Season points</th><th>Mission coins</th><th>Title</th><th class=\"num\">Played</th><th></th></tr></thead><tbody>' +\n      d.events.map((e, i) => '<tr><td><b>' + esc(e.en) + '</b> · ' + esc(e.ar) + '<div class=\"sub\">' + EKIND[e.kind] + ' · ' + status(e) + '</div></td><td>' + when(e.from) + '<br>→ ' + when(e.to) + '</td><td>×' + e.spMult + '</td><td>×' + e.missionMult + '</td><td>' + (e.titleId ? badge(titleById(e.titleId), 'en') + '<div class=\"sub\">after ' + e.titleGames + ' games</div>' : '—') + '</td><td class=\"num\">' + num(e.stats.players) + ' players<div class=\"sub\">' + num(e.stats.games) + ' games</div></td>' +\n        '<td><div class=\"row\"><button class=\"btn sm\" data-edit=\"' + i + '\">Edit</button><button class=\"btn sm bad\" data-del=\"' + i + '\">Delete</button></div></td></tr>').join('') + '</tbody></table>' : '<div class=\"card empty\">No events yet. Add Ramadan with one click above.</div>') +\n    '<h2>Limited skins</h2><div class=\"card\"><div class=\"sub\" style=\"margin-bottom:8px\">On sale only while an event of their kind is on; players keep them after.</div>' +\n      ['ramadan', 'eid'].map(k => '<div style=\"margin:6px 0\"><b>' + EKIND[k] + ':</b> ' + d.limited.filter(s => s.event === k).map(s => '<span class=\"tag\" style=\"margin:2px\">' + esc(s.id) + ' · ' + short(s.price) + '</span>').join('') + '</div>').join('') + '</div>';\n  const save = async list => { await act(() => api('/settings', { method: 'PUT', body: { events: list } }), 'Saved · the game shows it at once'); closeDrawer(); go(); };\n  const editor = (ev, idx) => {\n    const dr = drawer();\n    const e = ev ? { ...ev } : { id: '', kind: 'custom', ar: '', en: '', from: now, to: now + 7 * 86_400_000, spMult: 2, missionMult: 1, titleId: '', titleGames: 10 };\n    dr.innerHTML = '<button class=\"btn sm x\" id=\"cx\">Close ✕</button><h1>' + (idx >= 0 ? 'Edit event' : 'New event') + '</h1><div class=\"form\" style=\"margin-top:12px\">' +\n      '<label class=\"f\">Id (english, no spaces)<input id=\"ei\" value=\"' + esc(e.id) + '\"' + (idx >= 0 ? ' disabled' : '') + '></label>' +\n      '<label class=\"f\">Kind<select id=\"ek\">' + Object.entries(EKIND).map(([k, l]) => '<option value=\"' + k + '\"' + (k === e.kind ? ' selected' : '') + '>' + l + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">Arabic name<input id=\"ea\" dir=\"rtl\" value=\"' + esc(e.ar) + '\"></label><label class=\"f\">English name<input id=\"ee\" value=\"' + esc(e.en) + '\"></label>' +\n      '<label class=\"f\">Starts (Cairo)<input id=\"ef\" type=\"datetime-local\" value=\"' + toLocal(e.from) + '\"></label><label class=\"f\">Ends (Cairo)<input id=\"et\" type=\"datetime-local\" value=\"' + toLocal(e.to) + '\"></label>' +\n      '<label class=\"f\">Season points ×<input id=\"es\" type=\"number\" step=\"0.5\" min=\"1\" max=\"5\" value=\"' + e.spMult + '\"></label><label class=\"f\">Mission coins ×<input id=\"em\" type=\"number\" step=\"0.5\" min=\"1\" max=\"5\" value=\"' + e.missionMult + '\"></label>' +\n      '<label class=\"f\">Title for taking part<select id=\"eti\"><option value=\"\">none</option>' + d.titles.map(t => '<option value=\"' + t.id + '\"' + (t.id === e.titleId ? ' selected' : '') + '>' + esc(t.en + ' · ' + t.ar) + '</option>').join('') + '</select></label>' +\n      '<label class=\"f\">…after this many online games<input id=\"eg\" type=\"number\" min=\"0\" value=\"' + e.titleGames + '\"></label>' +\n      '</div><div class=\"sub\" style=\"margin-top:10px\">Ramadan and Eid dates move with the moon: check them before the event.</div><button class=\"btn gold\" id=\"esv\" style=\"margin-top:14px\">Save event</button>';\n    $('#cx', dr).onclick = closeDrawer;\n    $('#esv', dr).onclick = () => {\n      const v = { id: $('#ei', dr).value.trim().toLowerCase(), kind: $('#ek', dr).value, ar: $('#ea', dr).value, en: $('#ee', dr).value, from: fromLocal($('#ef', dr).value), to: fromLocal($('#et', dr).value),\n        spMult: Number($('#es', dr).value), missionMult: Number($('#em', dr).value), titleId: $('#eti', dr).value, titleGames: Number($('#eg', dr).value) };\n      if (!/^[a-z0-9_]{2,32}$/.test(v.id)) return toast('The id needs 2+ english letters, numbers or _', true);\n      if (!v.ar.trim() || !v.en.trim()) return toast('Write both names', true);\n      if (!(v.to > v.from)) return toast('The end must be after the start', true);\n      const list = d.events.map(({ stats, ...x }) => x);\n      if (idx >= 0) list[idx] = v; else { if (list.some(x => x.id === v.id)) return toast('That id is taken', true); list.push(v); }\n      save(list);\n    };\n  };\n  $('#enew').onclick = () => editor(null, -1);\n  main.querySelectorAll('[data-pre]').forEach(b => b.onclick = () => { const p = EPRESETS[b.dataset.pre]; editor({ ...p, from: fromLocal(p.from), to: fromLocal(p.to) }, -1); });\n  main.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => editor(d.events[b.dataset.edit], Number(b.dataset.edit)));\n  main.querySelectorAll('[data-del]').forEach(b => b.onclick = () => { const e = d.events[b.dataset.del]; if (confirm('Delete \"' + e.en + '\"?')) save(d.events.filter((_, i) => i !== Number(b.dataset.del)).map(({ stats, ...x }) => x)); });\n};\n\n/* ---------------- game settings ---------------- */\nRENDER.settings = async main => {\n  const s = await api('/settings');\n  const n = (id, label, v, extra) => '<label class=\"f\">' + label + '<input id=\"' + id + '\" type=\"number\" value=\"' + v + '\"' + (extra || '') + '></label>';\n  const list = (cls, label, arr) => arr.map((v, i) => '<label class=\"f\">' + label + ' ' + (i + 1) + '<input type=\"number\" class=\"' + cls + '\" value=\"' + v + '\"></label>').join('');\n  main.innerHTML = '<h1>Game settings</h1><div class=\"sub\">Changes reach the game at once, without a restart. Every change is in the activity log.</div>' +\n    '<h2>Maintenance</h2><div class=\"card\"><div class=\"form\"><label class=\"f\">Maintenance mode<span class=\"switch\"><input type=\"checkbox\" id=\"mo\"' + (s.maintenance.on ? ' checked' : '') + '> no new games start</span></label>' +\n      '<label class=\"f\" style=\"grid-column:span 2\">Message players see<input id=\"mm\" value=\"' + esc(s.maintenance.message) + '\"></label></div></div>' +\n    '<h2>Monthly prizes: Vodafone Cash</h2><div class=\"card\"><div class=\"form\">' +\n      '<label class=\"f\">Monthly prizes<span class=\"switch\"><input type=\"checkbox\" id=\"co\"' + (s.prizes.enabled ? ' checked' : '') + '> the top player of each game wins money</span></label>' +\n      n('ce', 'EGP for each game\\'s winner', s.prizes.egp) + n('cd', 'Days to give a number', s.prizes.claimDays) +\n      n('cg', 'Online games needed in the month', s.titles.minGames) +\n      '<label class=\"f\">Accepted numbers (prefixes)<input id=\"cp\" value=\"' + esc(s.prizes.prefixes.join(', ')) + '\"></label>' +\n    '</div><div class=\"sub\" style=\"margin-top:8px\">Four games, so up to ' + num(4 * s.prizes.egp) + ' EGP a month. The winner must be signed in (Google, Apple or phone). Vodafone Cash works on Vodafone lines (010). Coins can\\'t be turned into money.</div></div>' +\n    '<h2>Economy</h2><div class=\"card\"><div class=\"form\">' + n('es', 'Coins for a new player', s.economy.startCoins) + n('ea', 'Coins for a rewarded ad', s.economy.adReward) + n('ed', 'Rewarded ads a day', s.economy.adsPerDay) +\n      n('et', 'Coins for finishing the first-game guide', s.economy.tutorialCoins) + n('eb', 'Gift for coming back', s.economy.comebackCoins) + n('ey', '…after this many days away (0: off)', s.economy.comebackDays) + '</div>' +\n      '<div class=\"sub\" style=\"margin:12px 0 6px\">Daily reward, day by day (day 7 repeats after)</div><div class=\"form\">' + list('ek', 'Day', s.economy.streak) + '</div>' +\n      '<div class=\"sub\" style=\"margin:12px 0 6px\">Weekly leaderboard prizes, places 1–10 (paid every Monday)</div><div class=\"form\">' + list('ew', 'Place', s.economy.weeklyPrizes) + '</div></div>' +\n    '<h2>Play</h2><div class=\"card\"><div class=\"form\">' + n('pb', 'Seconds before computer players fill a table', s.play.botFillSeconds, ' min=\"2\" max=\"120\"') + n('pt', 'Seconds for a turn (dominoes)', s.play.turnSeconds, ' min=\"5\" max=\"60\"') + '</div></div>' +\n    '<div class=\"row\" style=\"margin-top:16px\"><button class=\"btn gold\" id=\"sv\">Save all settings</button><button class=\"btn\" id=\"rs\">Back to the defaults</button></div>';\n  $('#sv').onclick = async () => {\n    const vals = cls => [...main.querySelectorAll('.' + cls)].map(i => Number(i.value));\n    await act(() => api('/settings', { method: 'PUT', body: {\n      maintenance: { on: $('#mo').checked, message: $('#mm').value },\n      prizes: { enabled: $('#co').checked, egp: Number($('#ce').value), claimDays: Number($('#cd').value), prefixes: $('#cp').value.split(/[ ,]+/).filter(Boolean) },\n      titles: { minGames: Number($('#cg').value) },\n      economy: { startCoins: Number($('#es').value), adReward: Number($('#ea').value), adsPerDay: Number($('#ed').value), tutorialCoins: Number($('#et').value), comebackCoins: Number($('#eb').value), comebackDays: Number($('#ey').value), streak: vals('ek'), weeklyPrizes: vals('ew') },\n      play: { botFillSeconds: Number($('#pb').value), turnSeconds: Number($('#pt').value) },\n    } }), 'Settings saved'); go();\n  };\n  $('#rs').onclick = async () => { if (confirm('Put every setting back to the defaults?')) { await act(() => api('/settings/reset', { body: {} }), 'Back to the defaults'); go(); } };\n};\n\n/* ---------------- reports and support ---------------- */\nRENDER.reports = async main => {\n  const [r, s] = await Promise.all([api('/reports'), api('/support')]);\n  main.innerHTML = '<h1>Reports & support</h1>' +\n    '<h2>Player reports (' + r.rows.length + ')</h2>' + (r.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>About</th><th>Reason</th><th>By</th><th></th></tr></thead><tbody>' +\n      r.rows.map(x => '<tr><td>' + when(x.ts) + '</td><td><a href=\"#players/' + esc(x.about_id) + '\">' + esc(x.about_name || x.about_id) + '</a>' + (x.banned ? ' <span class=\"tag banned\">banned</span>' : x.muted_until > Date.now() ? ' <span class=\"tag\">muted</span>' : '') + '</td><td>' + esc(x.reason) + '</td><td>' + esc(x.from_name || x.from_id) + '</td><td><a class=\"btn sm\" href=\"#players/' + esc(x.about_id) + '\">Open</a></td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No reports</div>') +\n    '<h2>Support messages (' + s.rows.length + ')</h2>' + (s.rows.length ? s.rows.map(x => '<div class=\"card\" style=\"margin-bottom:8px\"><div class=\"sub\">#' + x.id + ' · ' + when(x.ts) + ' · ' + esc(x.name || 'player') + (x.contact ? ' · <span class=\"mono\">' + esc(x.contact) + '</span>' : '') + ' · ' + esc(x.app || '') + (x.user_id ? ' · <a href=\"#players/' + esc(x.user_id) + '\">player</a>' : '') + '</div><div style=\"white-space:pre-wrap;margin-top:6px\">' + esc(x.text) + '</div></div>').join('') : '<div class=\"card empty\">No messages</div>');\n};\n\n/* ---------------- purchases ---------------- */\nRENDER.purchases = async main => {\n  const d = await api('/purchases');\n  const byProduct = {}; d.rows.forEach(p => byProduct[p.product] = (byProduct[p.product] || 0) + 1);\n  main.innerHTML = '<h1>Purchases</h1><div class=\"sub\">Google Play purchases checked and credited by the server (the latest 300)</div>' +\n    '<div class=\"flags\">' + Object.entries(byProduct).map(([k, v]) => '<span class=\"flag\">' + esc(k) + ': ' + v + '</span>').join('') + '</div>' +\n    (d.rows.length ? '<div class=\"tablewrap\"><table><thead><tr><th>When</th><th>Player</th><th>Product</th><th class=\"num\">Coins</th><th>Order</th></tr></thead><tbody>' +\n      d.rows.map(p => '<tr><td>' + when(p.ts) + '</td><td><a href=\"#players/' + esc(p.user_id) + '\">' + esc(p.name || p.user_id) + '</a></td><td>' + esc(p.product) + '</td><td class=\"num\">' + (p.coins ? num(p.coins) : '') + '</td><td class=\"mono\">' + esc(p.order_id || '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">No purchases yet</div>');\n};\n\n/* ---------------- activity log ---------------- */\nRENDER.log = async main => {\n  const d = await api('/log');\n  main.innerHTML = '<h1>Activity log</h1><div class=\"sub\">What was done from this dashboard</div>' +\n    (d.rows.length ? '<div class=\"tablewrap\" style=\"margin-top:12px\"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Player</th><th>Details</th></tr></thead><tbody>' +\n      d.rows.map(x => '<tr><td>' + when(x.ts) + '</td><td class=\"mono\">' + esc(x.who) + '</td><td><b>' + esc(x.action) + '</b></td><td>' + (x.target ? '<a href=\"#players/' + esc(x.target) + '\" class=\"mono\">' + esc(x.target) + '</a>' : '') + '</td><td class=\"mono\" style=\"max-width:420px;word-break:break-word\">' + esc(x.detail || '') + '</td></tr>').join('') +\n      '</tbody></table></div>' : '<div class=\"card empty\">Nothing yet</div>');\n};\n\n// players linked from anywhere (#players/ID) open in the drawer\nwindow.addEventListener('hashchange', () => { const p = location.hash.split('/'); if (p[0] === '#players' && p[1] && state.view !== 'players') {} });\n\napi('/overview').then(start).catch(e => { if (e.message !== 'Signed out') { $('#root').innerHTML = '<div class=\"card login\">' + (e.message === 'admin_off' ? 'The dashboard is off: set <b>ADMIN_KEY</b> on the server, then reload.' : esc(e.message)) + '</div>'; } });\n</script>\n</body>\n</html>\n";
